    'archi-p2021-q18': { q: 'Determine the minimum number of bits required to encode the following signed number: 8,192.',
      x: '8,192 = 2¹³. On $n$ signed bits, the largest number is 2ⁿ⁻¹ − 1: you need 2ⁿ⁻¹ − 1 ≥ 2¹³, so $n$ − 1 ≥ 14 and $n$ = 15 (on 14 bits, the maximum is 8,191).' },
    'archi-p2021-q19': { q: 'Determine the minimum number of bits required to encode the following signed number: −8,192.',
      x: '−8,192 = −2¹³ is exactly the lower bound on 14 bits (−2¹³ to 2¹³ − 1): 14 bits are enough, one fewer than for 8,192.' },
    /* ================= midterm 2020-2021 (p2020, class of 2025) ================= */
    'archi-p2020-q1': { q: 'Convert [[1011 1001.0101|2]] into decimal.',
      x: '128 + 32 + 16 + 8 + 1 + 0.25 + 0.0625 = 185.3125.' },
    'archi-p2020-q2': { q: 'Convert [[E8.5|16]] into decimal.',
      x: '14 × 16 + 8 + 5 × 16⁻¹ = 232.3125.' },
    'archi-p2020-q3': { q: 'Convert 167.7 into hexadecimal (2 digits after the point).',
      o: ['[[A7.B3|16]]', '[[7A.B3|16]]', '[[A7.3B|16]]', '[[107.113|16]]'],
      x: '167 = 10 × 16 + 7; 10 = 0 × 16 + 10: remainders read from the last to the first; 0.7 × 16 = 11.2 → B; 0.2 × 16 = 3.2 → 3; stop at digit 2 (truncation). Result: A7.B3. Reading the remainders in the wrong order gives 7A.B3.' },
    'archi-p2020-q4': { q: 'Convert 92.3125 into binary.',
      o: ['[[101 1100.0101|2]]', '[[1 1101.0101|2]]', '[[101 1100.1010|2]]', '[[101 1100.0100|2]]'],
      x: 'Remainders of the successive divisions of 92 by 2: 0, 0, 1, 1, 1, 0, 1, read from the last to the first: 101 1100; 0.3125 × 2 = 0.625 → 0; 0.625 × 2 = 1.25 → 1; 0.25 × 2 = 0.5 → 0; 0.5 × 2 = 1 → 1. Result: 101 1100.0101. Reading the remainders in the wrong order gives 1 1101.0101.' },
    'archi-p2020-q5': { q: 'Convert [[13.25|8]] into binary.',
      o: ['[[1011.0101 01|2]]', '[[111.1010 1|2]]', '[[1011.0101 00|2]]', '[[1010.0101 01|2]]'],
      x: 'Through base 2, 3 bits per digit: 001 011.010 101 → 1011.0101 01. Dropping the leading zeros of a group (3 → 11 instead of 011) shifts everything: 111.1010 1.' },
    'archi-p2020-q6': { q: 'Convert [[2705.14|8]] into hexadecimal.',
      o: ['[[5C5.3|16]]', '[[5C5.0C|16]]', '[[B8A.30|16]]', '[[2705.14|16]]'],
      x: 'Through base 2, 3 bits per digit: 010 111 000 101.001 100. Groups of 4: 0101 1100 0101.0011 0000 → 5C5.3. Padding the fractional part on the left gives 5C5.0C: the zeros go on the right.' },
    'archi-p2020-q7': { q: 'Convert [[4BC.23|16]] into base 8.',
      o: ['[[2274.106|8]]', '[[2274.043|8]]', '[[4570.106|8]]', '[[2274.107|8]]'],
      x: 'Through base 2, 4 bits per digit: 0100 1011 1100.0010 0011. Groups of 3: 010 010 111 100.001 000 110 → 2274.106. Padding the fractional part on the left gives 2274.043: the zeros go on the right.' },
    'archi-p2020-q8': { q: 'Convert 80.25 into base 5 (2 digits after the point).',
      o: ['[[310.11|5]]', '[[13.11|5]]', '[[310.10|5]]', '[[310.12|5]]'],
      x: '80 = 16 × 5 + 0; 16 = 3 × 5 + 1; 3 = 0 × 5 + 3: remainders read from the last to the first; 0.25 × 5 = 1.25 → 1; 0.25 × 5 = 1.25 → 1; stop at digit 2 (truncation). Result: 310.11. Reading the remainders in the wrong order gives 13.11.' },
    'archi-p2020-q9': { q: 'Convert [[40|9]] into base 3.',
      x: 'Through base 10: 4 × 9 = 36; 36 = 12 × 3 + 0; 12 = 4 × 3 + 0; 4 = 1 × 3 + 1; 1 = 0 × 3 + 1 → 1100. Converting the number as if it were written in base 10 gives 1111.' },
    'archi-p2020-q10': { q: 'Convert [[1 0011 0011.1001 1|2]] into hexadecimal.',
      o: ['[[133.98|16]]', '[[133.13|16]]', '[[133.91|16]]', '[[998.98|16]]'],
      x: 'Groups of 4 from the point: 0001 0011 0011.1001 1000 → 133.98. Padding the fractional part on the left gives 133.13: the zeros go on the right.' },
    'archi-p2020-q11': { q: 'In terms of $n$, how many $n$-bit unsigned integers can be encoded?',
      x: '2ⁿ patterns, all used: from 0 to 2ⁿ − 1.' },
    'archi-p2020-q12': { q: 'In terms of $n$, how many $n$-bit signed integers can be encoded?',
      x: 'As many as unsigned: 2ⁿ, from −2ⁿ⁻¹ to 2ⁿ⁻¹ − 1 (half negative, the other half for 0 and the positive ones).' },
    'archi-p2020-q13': { q: 'In terms of $n$, what is the largest $n$-bit unsigned integer that can be encoded?',
      x: 'The word 11…1 is 2ⁿ − 1 (255 on 8 bits); 2ⁿ would need one more bit.' },
    'archi-p2020-q14': { q: 'In terms of $n$, what is the largest $n$-bit signed integer that can be encoded?',
      x: 'The word 01…1 is 2ⁿ⁻¹ − 1 (127 on 8 bits).' },
    'archi-p2020-q15': { q: 'In terms of $n$, what is the smallest $n$-bit signed integer that can be encoded?',
      x: 'The word 10…0 is −2ⁿ⁻¹ (−128 on 8 bits): one more negative number than positive ones.' },
    'archi-p2020-q16': { q: 'The one’s complement inverts each bit of a word. True or false?',
      x: 'True: this is the course sentence. The two’s complement inverts each bit and then adds one.' },
